def next_smallest_palindrome(num: int) -> int:
    s = str(num + 1)
    length = len(s)

    # Check if all digits are '9' -> next palindrome is 10..01
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    while True:
        if s == s[::-1]:
            return int(s)
        # Generate palindrome by mirroring left to right
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            pal = left + left[::-1]
        else:
            pal = left + left[-2::-1]
        if int(pal) >= int(s):
            s = pal
        else:
            # Increment the left half and mirror again
            left_num = int(left) + 1
            left = str(left_num)
            if len(left) > half:  # e.g. 999 + 1 = 1000, length increased
                length += 1
                s = '1' + ('0' * (length - 2)) + '1'
                half = (length + 1) // 2
                left = s[:half]
                continue
            if length % 2 == 0:
                s = left + left[::-1]
            else:
