def zip_tuples(t1, t2):
    # Determine which tuple is longer
    if len(t1) >= len(t2):
        longer, shorter = t1, t2
        cycle_shorter = cycle(shorter)
        # Pair longer[i] with cycled shorter elements
        return tuple((longer[i], next(cycle_shorter)) for i in range(len(longer)))
    else:
        longer, shorter = t2, t1
        cycle_shorter = cycle(shorter)
        # Pair cycled shorter elements with longer[i]
        return tuple((next(cycle_shorter), longer[i]) for i in range(len(longer)))

from typing import List

def permute_string(s: str) -> List[str]:
    if s == "":
        return [""]

    result = []
    s_sorted = sorted(s)
    used = [False] * len(s_sorted)

    def backtrack(path):
        if len(path) == len(s_sorted):
            result.append("".join(path))
            return
        for i in range(len(s_sorted)):
            if used[i]:
                continue
            if i > 0 and s_sorted[i] == s_sorted[i-1] and not used[i-1]:
                continue
            used[i] = True
            path.append(s_sorted[i])
            backtrack(path)
            path.pop()
            used[i] = False

    backtrack([])
    return result

