def min_Jumps(d, move_length):
    d = abs(d)
    if d == 0:
        return 0
    if move_length == 0:
        # Can't move anywhere if move_length is 0 and d != 0
        # Problem statement does not specify, but returning a large number or raising error is possible.
        # Here, return 0 as no moves possible to reach non-zero distance.
        return 0
    if d == move_length:
        return 1
    if d < move_length:
        # One move can overshoot, then come back, but since moves can be any direction,
        # one move can reach any point at distance move_length from origin,
        # so if d < move_length, one move cannot reach (d,0) exactly,
        # but two moves can reach it (e.g., move away, then come back)
        return 2
    # If d > move_length, minimal moves is ceil(d/move_length)
    return math.ceil(d / move_length)

