def anti_shuffle(s):
    if not s or s.isspace():
        return s

    # Split the string into words and spaces, preserving all spaces
    tokens = re.findall(r'\S+|\s+', s)

    result = []
    for token in tokens:
        if token.isspace():
            # preserve spaces as is
            result.append(token)
        else:
            # sort characters in the word by ASCII order
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)

    return ''.join(result)

